        'changes' => [
            'Agrega la pestaña Cursos combinados por establecimiento y año, conservando intactos los cursos, matrículas y planes originales.',
            'Permite crear grupos con dos o más cursos y evita que un curso pertenezca a dos combinaciones activas durante el mismo período.',
            'Consolida las necesidades por asignatura usando modalidades conjunta, separada, personalizada o mixta.',
            'La modalidad conjunta utiliza por defecto la mayor carga entre los cursos; la separada suma las cargas; la personalizada usa el total informado; y la mixta suma horas comunes más horas exclusivas por curso.',
            'Agrupa por nombre curricular normalizado para integrar asignaturas oficiales y horas de libre disposición vinculadas a la misma asignatura del plan común.',
            'Calcula primero las horas aula consolidadas y luego la necesidad contractual total del grupo, evitando sumar redondeos contractuales por asignatura.',
            'Mantiene 65/35 o 60/40 según la configuración del grupo y exige una selección explícita cuando los cursos poseen proporciones distintas.',
            'Impide combinar cursos con reglas contractuales especiales como NT1 o NT2 dentro de un grupo 65/35 o 60/40.',
            'La pestaña Asignación de horas muestra una sola necesidad por asignatura combinada e identifica todos los cursos cubiertos.',
            'Las asignaciones anteriores que dejan de coincidir con la necesidad consolidada no se eliminan automáticamente y quedan disponibles en Horas fantasmas para revisión manual.',
            'Actualiza los totales del establecimiento, la pestaña Horas por asignatura, el PDF individual y agrega la hoja Cursos combinados al Excel.',
            'Incorpora tablas de configuración, miembros y reglas por asignatura, además de vínculos de trazabilidad en las asignaciones docentes.',
        ],
        'roles' => ['Admin', 'Funcionario Directivo Establecimiento', 'Coordinador UATP', 'Coordinador GDP'],
