        ],
        'changes' => [
            'Clasifica Inasist o atraso y denominaciones equivalentes como descuento legal.',
            'Asigna la prioridad Legal - Inasistencias y atrasos antes de APV, descuentos gremiales, ahorros y descuentos con cuota.',
            'El descuento conserva su condición sin cuota y no participa en el orden cronológico global de cuotas.',
            'Las cuotas continúan ordenándose entre sí por su inicio calculado, pero sólo después de aplicar los descuentos legales y demás conceptos de prelación anterior.',
            'La corrección se refleja en el consumo real del tope del 45%, la tabla de detalle y las exportaciones.',
            'No incorpora migraciones ni modifica datos almacenados.',
