        'roles' => ['Admin'],
    ],
    '2026.7.1.326' => [
        'date' => '2026-07-23',
        'module' => 'Endeudamiento',
        'title' => 'Orden global de cuotas por inicio calculado',
        'files' => [
            'app/Services/MaeTopesCalculatorService.php',
            'config/changelog.php',
        ],
        'changes' => [
            'Reemplaza el orden por tipo incorporado en el parche 325 para todos los descuentos que poseen una cuota actual positiva.',
            'Agrupa virtualmente todas las cuotas del funcionario en un único conjunto, sin separar por crédito, caja de compensación, cooperativa, seguro, institución, subgrupo ni prioridad comercial.',
            'Ordena las cuotas por mes de inicio calculado ascendente, desde la obligación más antigua hasta la más reciente.',
            'Cuando dos cuotas tienen el mismo inicio calculado, utiliza la prioridad vigente, la cuota más avanzada, el orden original y el identificador como desempates estables.',
            'Los descuentos sin cuota mantienen su ubicación relativa y el orden de prelación existente; sólo se reemplazan entre sí las posiciones ocupadas por descuentos con cuota.',
            'Las cuotas indefinidas con número de cuota positivo participan en el orden cronológico aunque no tengan total de cuotas.',
            'Actualiza los motivos del detalle para indicar cuándo el descuento fue aplicado o rechazado por el orden cronológico de cuotas.',
            'El orden se utiliza tanto para consumir el tope del 45% como para la tabla de detalle y las exportaciones.',
            'No incorpora migraciones ni modifica registros almacenados.',
        ],
        'roles' => ['Admin'],
    ],
    '2026.7.1.325' => [
        'date' => '2026-07-23',
        'module' => 'Endeudamiento',
        'title' => 'Orden cronológico exclusivo para descuentos con cuota',
        'files' => [
