            'config/changelog.php',
        ],
        'changes' => [
            'Mantiene íntegramente la prelación existente por tipo de descuento durante el cálculo del tope de endeudamiento.',
            'Dentro de cada tipo, reordena exclusivamente los descuentos que poseen una cuota actual positiva, desde la obligación más antigua hasta la más reciente.',
            'Determina la antigüedad mediante el mes de inicio inferido desde el período MAE y la cuota actual; ante empate utiliza la cuota y el orden original como criterios de desempate.',
            'Los descuentos sin cuota y los descuentos indefinidos informados con cuota 0 conservan exactamente su posición relativa y su tratamiento anterior.',
            'El nuevo orden se aplica al cálculo real del 45%, al detalle de resolución y a las exportaciones que reutilizan el mismo servicio.',
            'No modifica topes, montos, clasificación, prioridad entre tipos de descuento ni estructura de base de datos.',
        ],
        'roles' => ['Admin'],
    ],
    '2026.7.1.324' => [
