            'config/changelog.php',
        ],
        'changes' => [
            'Normaliza a UTF-8 el texto obtenido desde el extractor PHP de respaldo antes de aplicar expresiones regulares.',
            'Corrige la lectura de PDFs digitales de una hoja cuyos caracteres especiales venían en Windows-1252 o ISO-8859-1, impidiendo detectar N°, tildes y etiquetas del formulario.',
            'Mejora la captura del trabajador cuando los datos vienen en líneas separadas: apellido paterno, apellido materno, nombres, RUN, edad y sexo.',
            'Corrige la lectura de fechas por etiquetas independientes FECHA EMISION LICENCIA y FECHA INICIO DE REPOSO.',
            'Evita que el DV 0 de la licencia sea tratado como campo vacío en las advertencias de extracción.',
            'Mantiene compatibilidad con smalot/pdfparser cuando esté instalado y con el extractor PHP liviano cuando no exista la librería.',
        ],
        'impact' => 'Permite que el formulario se precargue correctamente con PDFs digitales tipo formulario de una hoja, como los documentos que no incluyen comprobante estructurado final.',
    ],

    '2026.7.1.293' => [
