            'summary' => 'Ajusta el cálculo automático de viático y referencia de reembolso para funcionarios de Administración Central usando el catálogo vigente: con grado aplica Código Administrativo por tramo de grado, y sin grado con escalafón Docente aplica Docente / Docentes.',
