            'summary' => 'Actualiza las notificaciones por correo del flujo AC y pasajes aéreos para adjuntar el expediente documental correspondiente a cada etapa, incluyendo cometido firmado, citación o invitación, documentos complementarios, solicitud de pedido firmada, reserva y CDP cuando corresponda.',
