                5 => 'Se agrega excepción para solicitudes AAEE cuyo área de desempeño sea Celador, caso en que no se aplica la regla mínima de 7 días.',
                6 => 'La continuidad se busca para todas las solicitudes mediante solicitud anterior correlativa, validando RUT titular desde reemplazos_personal.rut y RUT reemplazante desde users.rut asociado a postulant_profile_id, ambos normalizados.',
                7 => 'Cuando se detecta continuidad válida, la nueva solicitud queda asociada a la solicitud anterior y se registra trazabilidad de continuidad y regla mínima aplicada.',
                8 => 'Se agrega el campo ¿Establecimiento con unidocencia? al mantenedor de establecimientos para exceptuar la regla mínima docente cuando corresponda.',
                9 => 'Se muestran mensajes normativos diferenciados para docentes, sala cuna/JUNJI y asistentes de la educación cuando no se cumplen las condiciones de envío.',
