            'items' => [
                1 => 'Se agregan estilos reutilizables para botones de Cometido funcionario con variantes primaria, secundaria, aprobar, observar, rechazar y documentos.',
                2 => 'Los botones superiores Volver y Corregir/editar se alinean con la jerarquía visual del nuevo diseño.',
                3 => 'Las acciones CDP Aprobar y derivar a GDP y Rechazar CDP y autorizar sin gasto dejan de usar botones Bootstrap planos y pasan a botones consistentes, sobrios y con mejor espaciado.',
                4 => 'Las acciones UATP Aprobar, Observar y Rechazar se ajustan al mismo sistema visual de botones, conservando textos, formularios, validaciones y rutas existentes.',
                5 => 'Los botones Ver/Descargar de citación, CDP y documentos adjuntos se transforman en acciones compactas de documento, manteniendo el destacado del documento CDP.',
                6 => 'No se modifican timeline, historial, reglas backend, controladores, rutas, migraciones ni permisos por rol activo.',
