                8 => 'funcionario_daf',
            ],
            'items' => [
                1 => 'El bloque Resumen se reorganiza como tarjeta visual de identificación con campos destacados para fecha, establecimiento, funcionario, calidad jurídica, estamento y cargo/función.',
                2 => 'El Detalle del viaje se presenta como tarjeta de destino y duración, con agrupación clara de región, comuna, institución, destino específico, periodo y horario.',
                3 => 'El bloque Motivo y actividad se rediseña con chips de transporte, beneficios solicitados, citación/invitación, declaración jurada, descripción de actividades y resumen CDP autorizado cuando corresponda.',
                4 => 'Documentos adjuntos pasa a una lista visual de tarjetas con icono, tipo de documento, nombre, tamaño y acciones Ver/Descargar, destacando el documento CDP.',
                5 => 'Se agregan estilos reutilizables para tarjetas informativas, grillas de datos, chips, resumen CDP aprobado y documentos, sin modificar rutas, controladores, migraciones ni reglas backend.',
                6 => 'Se mantiene intacta la barra de avance del trámite, el historial visual del trámite, la revisión CDP rediseñada y las tarjetas de etapas UATP, GDP y DAF/Rendición.',
            ],
            'published_at' => '2026-05-12 20:50:00',
