        [
            'version' => '2026.5.11.35',
            'title' => 'Trámites: rediseño visual de revisión CDP',
            'summary' => 'Se rediseña la sección Revisión CDP - Planificación del detalle de Cometido funcionario para facilitar la asignación diaria de viático y reembolso, manteniendo la línea de estado y el historial del trámite.',
