                3 => 'coordinador_plani',
            ],
            'items' => [
                1 => 'La revisión CDP se presenta como bloque visual principal de la vista, con encabezado, estado, alerta informativa y selector de catálogo con mejor jerarquía visual.',
                2 => 'Las grillas diarias de viático y reembolso se reorganizan en tarjetas independientes con switch Autorizar pago, opciones 100%, 40% y 0%, y totales destacados por beneficio.',
                3 => 'Se agrega un panel de Resumen CDP con total de viático, total de reembolso como tope máximo, total general, referencia CDP, adjunto obligatorio y observación opcional.',
                4 => 'La acción de rechazo queda integrada bajo la misma sección visual mediante observación presupuestaria obligatoria, sin cambiar rutas ni reglas de autorización.',
                5 => 'Se mantiene intacta la barra de avance del trámite y el historial visual del trámite; el cambio es de presentación y organización de la revisión CDP.',
