            'published_at' => '2026-05-12 20:20:00',
        ],
        [
            'version' => '2026.5.11.34',
            'title' => 'Trámites: porcentaje 0% por día en CDP',
            'summary' => 'Planificación puede asignar 0% en días específicos de viático o reembolso durante la revisión CDP, dejando esos días con valor cero sin deshabilitar todo el beneficio.',
            'roles' => [
                1 => 'admin',
                2 => 'supervisor_plani',
                3 => 'coordinador_plani',
            ],
            'items' => [
                1 => 'En las grillas diarias de CDP para viático y reembolso se agrega la opción 0% junto a 100% y 40%.',
                2 => 'La opción 0% permite dejar un día específico con valor diario $0 sin apagar el beneficio completo.',
                3 => 'El backend valida 100%, 40% o 0% por día y guarda los días al 0% con porcentaje 0, valor diario 0 y monto 0.',
                4 => 'Se conserva el switch general para autorizar o deshabilitar completamente viático o reembolso cuando corresponda.',
                5 => 'No se modifican rutas, documentos, flujo de estados ni la autorización por rol activo.',
