        [
            'version' => '2026.5.11.33',
            'title' => 'Trámites: habilitar o deshabilitar beneficios en CDP',
            'summary' => 'Planificación puede autorizar o deshabilitar por separado el pago de viático y/o reembolso en la revisión CDP, dejando valores diarios en cero cuando corresponda.',
            'roles' => [
                1 => 'admin',
                2 => 'supervisor_plani',
                3 => 'coordinador_plani',
            ],
            'items' => [
                1 => 'En la revisión CDP de Cometido funcionario se agrega un switch por beneficio solicitado para autorizar o deshabilitar viático y reembolso de manera independiente.',
                2 => 'Por defecto cada beneficio solicitado queda habilitado y mantiene la grilla diaria con selección 100% o 40%.',
                3 => 'Si Planificación deshabilita un beneficio, la tabla muestra $0 para todos los días y bloquea la selección de porcentaje.',
                4 => 'El backend guarda el detalle diario del beneficio deshabilitado con porcentaje 0, valor diario 0 y monto 0, manteniendo trazabilidad y totales consistentes.',
                5 => 'El detalle de montos aprobados muestra los días sin pago como No autorizado en vez de mostrar un porcentaje aplicable.',
                6 => 'Se mantiene la autorización por rol activo incorporada en el parche anterior y no se modifican rutas, documentos ni flujo de estados.',
            ],
            'published_at' => '2026-05-12 19:45:00',
        ],
        [
            'version' => '2026.5.11.32',
            'title' => 'Trámites: acciones de Cometido funcionario según rol activo',
