            'items' => [
                1 => 'Las banderas de revisión UATP, CDP y GDP se calculan usando el rol activo de sesión.',
                2 => 'La vista de detalle deja de habilitar acciones por roles asignados no activos, evitando que un usuario con doble rol vea o ejecute acciones de Planificación cuando está operando como funcionario_estab.',
                3 => 'Las acciones backend de aprobar/rechazar/observar UATP, aprobar/rechazar CDP y accesos relacionados quedan protegidas por rol activo, no por roles acumulados del usuario.',
                4 => 'No se modifica la lógica de montos diarios CDP, documentos, historial, rutas ni migraciones del parche anterior.',
