        [
            'version' => '2026.5.11.31',
            'title' => 'Trámites: CDP con asignación diaria de montos 100%/40%',
            'summary' => 'Planificación puede aprobar CDP asignando valores diarios al 100% o 40% para viático y/o reembolso, con totales separados y total CDP.',
            'roles' => [
                1 => 'admin',
                2 => 'supervisor_plani',
                3 => 'coordinador_plani',
            ],
            'items' => [
                1 => 'En la revisión CDP de Cometido funcionario se agrega selección de estamento y cargo/función desde el catálogo vigente de Viáticos y Reembolsos.',
                2 => 'Para cada día del cometido, Planificación puede elegir independientemente si aplica 100% o 40%.',
                3 => 'Si la solicitud incluye viático, el sistema calcula y guarda el viático fijo autorizado por día y total.',
                4 => 'Si la solicitud incluye reembolso, el sistema calcula y guarda el tope diario y total máximo reembolsable, separado del viático.',
                5 => 'Cuando una solicitud incluye ambos beneficios, se muestran y guardan grillas independientes para viático y reembolso, permitiendo porcentajes distintos por día y por tipo.',
                6 => 'El detalle del trámite muestra el catálogo aplicado, el detalle diario, el total de viático, el total máximo de reembolso y el total CDP.',
                7 => 'La aprobación CDP registra en historial la referencia, archivo, catálogo aplicado y montos autorizados; el rechazo CDP limpia cualquier asignación de montos previa.',
            ],
            'published_at' => '2026-05-12 19:15:00',
        ],
        [
