            'items' => [
                1 => 'La vista Catálogos → Viáticos y Reembolsos incorpora una tarjeta para seleccionar una fecha de referencia y activar los registros vigentes a esa fecha.',
                2 => 'La acción marca como activos todos los registros cuyo tramo de vigencia incluye la fecha seleccionada.',
                3 => 'La misma acción desactiva los registros que queden fuera de la fecha de referencia, evitando múltiples tramos activos simultáneamente.',
                4 => 'Al finalizar, el sistema informa cuántos registros estaban vigentes, cuántos fueron activados y cuántos fueron desactivados por estar fuera de vigencia.',
                5 => 'No se modifican los montos, tramos, cargos, estamentos ni la futura integración con Cometido funcionario.',
