                2 => 'Se cargan los valores iniciales informados para los tramos 2025, enero-mayo 2026 y junio-diciembre 2026.',
                3 => 'Se agrega un mantenedor en Catálogos → Viáticos y Reembolsos, con filtros por estamento, cargo/función y estado activo.',
                4 => 'El catálogo queda disponible para administración y consulta; la integración automática con Cometido funcionario queda preparada para un parche posterior.',
