                3 => 'Se incorpora una advertencia dinámica al seleccionar Fecha desde cuando el cometido inicia a menos de 10 días hábiles, sin bloquear el envío para permitir casos excepcionales.',
                4 => 'La advertencia indica que solicitudes fuera del plazo recomendado podrían quedar sujetas a observación, rechazo o imposibilidad de gestión oportuna.',
