            'summary' => 'Se agrega la segunda etapa del flujo de Cometido funcionario: derivación automática desde UATP hacia Planificación/CDP cuando existe gasto y hacia GDP cuando no existe gasto, con acciones de aprobación o rechazo de CDP.',
