            'items' => [
                1 => 'Al aprobar UATP, las solicitudes sin viático ni devolución de gastos pasan directamente a GDP para resolución.',
                2 => 'Al aprobar UATP, las solicitudes con viático o devolución de gastos pasan a revisión CDP por Planificación.',
                3 => 'Planificación puede aprobar CDP, registrar referencia/número y observación, dejando la solicitud disponible para GDP.',
                4 => 'Planificación puede rechazar CDP; el trámite queda autorizado sin gasto y advierte que no corresponde viático, devolución ni reembolso por falta de disponibilidad presupuestaria.',
                5 => 'La vista de detalle incorpora tarjetas de acción para CDP y una tarjeta informativa para GDP, además de mostrar referencia y observación CDP cuando existan.',
            ],
            'published_at' => '2026-05-11 17:15:00',
        ],
        [
