            'title' => 'Trámites: declaración jurada en Cometido funcionario',
            'summary' => 'Se agrega declaración jurada de veracidad al formulario web de Cometido funcionario y se condiciona el envío a la aceptación de la declaración junto con la completitud de campos y documentos requeridos.',
