                2 => 'Se agrega checkbox de aceptación obligatorio para enviar la solicitud a UATP; el borrador puede guardarse sin aceptación.',
                3 => 'El botón Enviar solicitud queda deshabilitado en frontend hasta completar campos obligatorios, adjuntar Oficio y Formulario de Cometido cuando corresponda y aceptar la declaración.',
                4 => 'El backend valida igualmente la aceptación de la declaración al enviar, evitando envíos directos sin aceptación desde el navegador.',
