                2 => 'El funcionario del trámite se selecciona desde el último padrón activo/cargado del establecimiento y se autocompletan nombre, RUT, calidad jurídica, estamento y cargo/función desde reemplazos_personal.',
                3 => 'El formulario incorpora detalle de viaje, región y comuna dinámica, transporte, motivo, descripción de actividades, citación/invitación y solicitud de devolución de gastos o viático según estamento.',
