            'items' => [
                1 => 'El manejador global de excepciones deja de enviar alertas críticas directamente con Mail y ahora usa NotificationAudit, registrando estados pending, sent o failed en notification_dispatch_logs.',
                2 => 'Las alertas de errores 500, errores de vista, rutas, base de datos, storage, SMTP, importaciones y jobs fallidos se registran con event_key y contexto técnico para trazabilidad administrativa.',
                3 => 'Los destinatarios de alertas críticas se pueden configurar con CRITICAL_ALERT_EMAILS en .env, manteniendo los correos internos actuales como respaldo si no se define la variable.',
