// 2026.7.1.242 - Solicitudes de reemplazo: fix Error 500 antecedentes por columna users.name
// - Corrige la carga anticipada de postulante.user y contratoPostulante.user en solicitudes anteriores relacionadas.
// - Se elimina la columna inexistente users.name del SELECT, manteniendo nombres, apellido_paterno, apellido_materno y email.
// - Mantiene la búsqueda de antecedentes por RUT del titular, mismo tipo de reemplazo y estados aceptada/cerrado/cerrada.
];

// 2026.5.18.207: DAF contable para compromiso y devengo antes del pago de viáticos y reembolsos.

// 2026.5.18.210: Notificación configurable a Servicios Generales por vehículo institucional.

// 2026.7.1.243 - Solicitudes de reemplazo: bandeja de finiquitos por continuidad del reemplazante
// - Agrega vista para admin, coordinador_gdp y funcionario_slep con reemplazos aceptados/cerrados cuyo término tiene más de 6 días.
// - La elegibilidad considera continuidad por RUT del reemplazante, usando postulante, contrato asociado o rut_reemplazo_normalizado.
// - Permite marcar finiquito pagado con usuario, fecha y observación de trazabilidad.
// - Se agregan columnas finiquito_pagado, finiquito_pagado_por_user_id, finiquito_pagado_at y finiquito_observacion.

// 2026.7.1.244 - Solicitudes de reemplazo: fix Error 500 relación planiReaperturaUser
// - Corrige Error 500 en bandeja de solicitudes por relación inexistente planiReaperturaUser en SolicitudReemplazo.
// - Agrega relaciones uatpReaperturaUser y planiReaperturaUser hacia users.
// - Agrega campos de reapertura UATP/Planificación al modelo para trazabilidad administrativa.

// 2026.7.1.245 - Solicitudes de reemplazo: finiquitos por periodo laboral efectivo
// - La bandeja de finiquitos ahora exige periodo completo con fecha_inicio_trabajo y fecha_termino.
// - Los filtros de periodo consideran solapamiento del periodo laboral: fecha_termino >= desde y fecha_inicio_trabajo <= hasta.
// - La continuidad por RUT del reemplazante se evalua sobre el ultimo periodo laboral completo, ordenado por fecha_termino y fecha_inicio_trabajo.
// - Se rediseña la vista con tarjetas de resumen, regla de control tipo flujo y acciones visuales similares al modulo de cometidos funcionarios.

// 2026.7.1.246 - Solicitudes de reemplazo: rediseño visual finiquitos tipo cometidos funcionarios
// - Se reemplaza el diseño simple de la vista de finiquitos por estructura visual homologada al modulo Cometidos Funcionarios.
// - Se incorporan header institucional, cards de resumen, paneles, cards de flujo, tabla estilizada, badges y botones tipo cf-*.
// - Se mejora el modal de marcacion de finiquito pagado con tarjeta de confirmacion, datos del periodo laboral y advertencia administrativa.
// - Se mantiene la regla de negocio basada en fecha_inicio_trabajo, fecha_termino, continuidad por RUT y corte de mas de 6 dias.

// 2026.7.1.248 - Solicitudes de reemplazo: finiquitos por tipo de gestión, firmante y generación PDF
// - Separa la bandeja en pestañas Asistentes, JUNJI/Sala Cuna, Docentes Matriz C y Todos.
// - JUNJI se identifica mediante establecimientos.sala_cuna = true y sí aplica gestión de finiquito.
// - Docentes no JUNJI quedan como cese administrativo para control de Matriz C, sin acción de generación de finiquito.
// - Agrega generación de finiquito en PDF desde la bandeja; al generar, el estado del finiquito pasa a generado.
// - Agrega selector de firmante desde la matriz de Dirección Ejecutiva y subrogantes; si es subrogante, el documento indica Director Ejecutivo (S).
// - Normaliza el tratamiento personal del documento a Don(a), evitando Don/Doña rígido.

// 2026.7.1.249 - Solicitudes de reemplazo: formato original para PDF de finiquito
// - Ajusta la plantilla PDF del finiquito para conservar estructura y redacción base del documento original FINIQUITOS LOTA.
// - Incorpora encabezado con logos institucionales y Gobierno de Chile en el PDF generado.
// - Ajusta tipografía, márgenes, título, cláusulas, interlineado y bloque de firmas para asemejar el formato del finiquito original.
// - Mantiene selección dinámica de firmante; si corresponde a subrogante, se imprime Director Ejecutivo (S) en texto y pie de firma.
// - Mantiene tratamiento neutro Don(a) en reemplazo de Don/Doña.

// 2026.7.03.023 - Licencias Médicas: importación streaming XLSX seguimiento histórico
// - Corrige error 504 al procesar planillas de seguimiento con hojas de más de 10.000 registros.
// - Incorpora lectura streaming con ZipArchive/XMLReader para no cargar el libro completo en memoria.
// - Reduce carga de historial por fila y mantiene trazabilidad en licencias_medicas_importaciones.


// 2026.7.09.039 - Agendamiento: administradores obligatorios y notificaciones solo a responsables asignados
// - Las notificaciones de solicitud pendiente, anulación y cambio de horario se envían solo a administradores explícitamente asignados a la sala/recurso.
// - Se elimina el fallback de notificación por grupos de rol.
// - Cada sala/recurso debe tener al menos un administrador para guardar el mantenedor o permitir nuevos agendamientos.
// - La administración de salas queda determinada por usuario asignado, salvo admin global.

// 2026.7.13.045 - Estudiantes PIE: horas contrato asociadas y bolsa para Dotación Establecimiento
// - Convierte las horas PROF EDUC. DIF a horas de contrato de 44 horas según la proporción 65/35 o 60/40 aplicada a cada curso.
// - Muestra en el resumen PIE las horas contrato exactas y la bolsa contractual redondeada hacia arriba.
// - Dotación Establecimiento utiliza la nueva bolsa contractual para asignar horas a Educadoras Diferenciales PIE.
// - En establecimientos con proporciones mixtas, calcula curso a curso, suma los minutos exactos y redondea una sola vez el total.
